WITH positioned AS (SELECT mktcode,tgtcode,bizdate,lastPx,quantRatio/10000.0 AS value,MIN(quantRatio/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 59 PRECEDING AND CURRENT ROW) AS minimum,MAX(quantRatio/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 59 PRECEDING AND CURRENT ROW) AS maximum FROM `newzl`.`hsj_stock_hq_basic`), reference_value AS (SELECT b.lastPx/10000.0 AS value FROM `newzl`.`hsj_stock_hq_basic` b JOIN `newzl`.`hsj_stock_code_info` s ON s.mktcode=b.mktcode AND s.tgtcode=b.tgtcode WHERE s.name='比亚迪' AND b.bizdate='2026-04-14') SELECT p.mktcode,p.tgtcode,p.bizdate FROM positioned p CROSS JOIN reference_value r WHERE p.bizdate='2026-04-14' AND p.value>p.minimum AND p.value<p.maximum AND (p.value-p.minimum)/NULLIF(p.maximum-p.minimum,0)>=0.75 AND p.lastPx/10000.0<r.value;
